  ) AS t(cod, membrete)
  LOOP
    IF EXISTS (SELECT 1 FROM plan_inspecciones WHERE plan_id = v_plan AND codigo_dea = r.cod AND desenlazado_en IS NULL) THEN
      v_ya := v_ya + 1;
    ELSIF EXISTS (SELECT 1 FROM plan_inspecciones WHERE plan_id <> v_plan AND codigo_dea = r.cod AND desenlazado_en IS NULL AND ejecucion = 'EN_EJECUCION') THEN
      v_saltados := v_saltados + 1;
      RAISE NOTICE 'Se salta % porque sigue en ejecución en otro plan.', r.cod;
    ELSIF EXISTS (SELECT 1 FROM plan_inspecciones WHERE plan_id = v_plan AND codigo_dea = r.cod AND desenlazado_en IS NOT NULL) THEN
      UPDATE plan_inspecciones SET desenlazado_en = NULL, desenlazado_por = NULL, enlazado_en = NOW()
      WHERE plan_id = v_plan AND codigo_dea = r.cod;
      v_reenlazados := v_reenlazados + 1;
    ELSE
      INSERT INTO inspecciones (codigo_dea, membrete, origen, estado)
      VALUES (r.cod, r.membrete, 'NUEVA', 'BORRADOR')
      RETURNING id INTO v_insp;
      INSERT INTO plan_inspecciones (plan_id, inspeccion_id, codigo_dea)
      VALUES (v_plan, v_insp, r.cod);
      v_nuevos := v_nuevos + 1;
    END IF;
  END LOOP;

  UPDATE plan_inspecciones SET desenlazado_en = NOW()
  WHERE plan_id = v_plan AND desenlazado_en IS NULL
    AND codigo_dea IN ('OD02281608', 'OD02591613', 'OD02981603', 'S0532D1601', 'S1739D1608', 'S4705D1607');
  GET DIAGNOSTICS v_quitados = ROW_COUNT;

  RAISE NOTICE 'Agregados: %, re-enlazados: %, ya estaban: %, saltados: %, desenlazados: %', v_nuevos, v_reenlazados, v_ya, v_saltados, v_quitados;
END
